sys_script_client.script:
function onSubmit() {
    var start = g_form.getValue('start');
    var end = g_form.getValue('end');
    var capStr = g_form.getValue('capacity');
    var entryFeeStr = g_form.getValue('entry_fee');
    var sponsorAmtStr = g_form.getValue('sponsor_amount');

    g_form.clearMessages();

    if (start && end && start >= end) {
        g_form.addErrorMessage('Start date must be before End date.');
        return false;
    }

    if (capStr !== '') {
        var capacity = parseInt(capStr, 10);
        if (isNaN(capacity) || capacity <= 0) {
            g_form.addErrorMessage('Capacity must be a positive integer.');
            return false;
        }
    }

    if (entryFeeStr !== '') {
        var entryFee = parseFloat(entryFeeStr.replace(/[^0-9.-]/g, ''));
        if (!isNaN(entryFee) && entryFee < 0) {
            g_form.addErrorMessage('Entry Fee cannot be negative.');
            return false;
        }
    }

    if (sponsorAmtStr !== '') {
        var sponsorAmt = parseFloat(sponsorAmtStr.replace(/[^0-9.-]/g, ''));
        if (!isNaN(sponsorAmt) && sponsorAmt < 0) {
            g_form.addErrorMessage('Sponsor Amount cannot be negative.');
            return false;
        }
    }
    return true;
}
